use std::{hint::black_box,time::Instant};use paper1_rns_bfv::{asymred,MODULI};
fn main(){let q=MODULI[0];let d=16793599u64;let xs:Vec<u128>=(0..200000u128).map(|i|(i.wrapping_mul(0x9e3779b97f4a7c15u128)^(i<<61))%((q as u128)*(q as u128))).collect();let t=Instant::now();let mut c=0u64;for &z in &xs{c^=black_box(asymred(black_box(z),q,55,d).unwrap());}let e=t.elapsed();println!("asymred_candidate n={} elapsed_ns={} ns/op={:.2} checksum={}",xs.len(),e.as_nanos(),e.as_nanos()as f64/xs.len()as f64,c);let t=Instant::now();for &z in &xs{c^=black_box((black_box(z)%q as u128)as u64);}let e=t.elapsed();println!("u128_remainder_baseline n={} elapsed_ns={} ns/op={:.2} checksum={}",xs.len(),e.as_nanos(),e.as_nanos()as f64/xs.len()as f64,c);}
